import{_ as t,o as e,c as a,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2017-NOV-01 :: Ceph Developer Monthly","description":"","frontmatter":{"title":"2017-NOV-01 :: Ceph Developer Monthly","date":"2017-12-18T00:00:00.000Z","updated":"2017-12-19T00:00:00.000Z","tags":["Ceph","Distributed Storage","CRUSH Algorithm","High Availability","Scalability"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2017/2017-NOV-01_-_-_Ceph_Developer_Monthly.md","filePath":"posts/2017/2017-NOV-01_-_-_Ceph_Developer_Monthly.md","lastUpdated":1780459816000}'),i={name:"posts/2017/2017-NOV-01_-_-_Ceph_Developer_Monthly.md"};function r(s,l,n,p,h,_){return e(),a("div",null,[...l[0]||(l[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>会议地点</strong>： CEM开发者月度会议</p><p><strong>参会人员</strong>： Greg, Josh, Sage, Mark, Adam, Casey 等</p><p><strong>会议主题</strong>：</p><ol><li><strong>Ceph PG 日志问题</strong>： 讨论了在使用 SSD 时，PG 日志导致的性能问题，并提出了改进方案。</li><li><strong>快照修剪问题</strong>： 分析了快照修剪过程中存在的问题，并提出了改进方案。</li><li><strong>C++17 async 库的使用</strong>： 讨论了在 Ceph 中使用 C++17 async 库进行代码重构的可能性。</li></ol><h3 id="关键细节" tabindex="-1">关键细节： <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节：&quot;">​</a></h3><p><strong>1. Ceph PG 日志问题</strong></p><ul><li><strong>问题</strong>： 使用 SSD 时，PG 日志导致的写放大、CPU 和内存开销等问题。</li><li><strong>改进方案</strong>： <ul><li>在 SSD 上使用环形缓冲区存储 PG 日志，减少写放大和 CPU 开销。</li><li>使用 FIFO 压缩模式，简化数据结构并提高效率。</li><li>将 PG 日志与其他内部元数据分开存储，减少内存占用。</li></ul></li></ul><p><strong>2. 快照修剪问题</strong></p><ul><li><strong>问题</strong>： 快照修剪过程中效率低下、数据结构复杂。</li><li><strong>改进方案</strong>： <ul><li>使用增量数据结构，减少 CPU 开销。</li><li>优化快照修剪算法，提高效率。</li><li>将快照修剪与缓存淘汰分开处理。</li></ul></li></ul><p><strong>3. C++17 async 库的使用</strong></p><ul><li><strong>目的</strong>： 使用 C++17 async 库进行代码重构，提高代码的可读性和可维护性。</li><li><strong>方案</strong>： <ul><li>将 Ceph 的部分代码从阻塞模式改为异步模式。</li><li>使用 C++17 async 库提供的功能，简化代码结构。</li></ul></li></ul><h3 id="决定的事项" tabindex="-1">决定的事项： <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项：&quot;">​</a></h3><ul><li>将 PG 日志存储在环形缓冲区中，并使用 FIFO 压缩模式。</li><li>优化快照修剪算法，并使用增量数据结构。</li><li>开始使用 C++17 async 库进行代码重构。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h3><ul><li>完成环形缓冲区和 FIFO 压缩模式的实现。</li><li>优化快照修剪算法，并使用增量数据结构。</li><li>完成代码重构，并评估其效果。</li></ul><h3 id="改进后的总结" tabindex="-1">改进后的总结： <a class="header-anchor" href="#改进后的总结" aria-label="Permalink to &quot;改进后的总结：&quot;">​</a></h3><p>本次会议主要讨论了 Ceph 分布式存储系统中的PG日志问题、快照修剪问题和代码重构的可能性。针对PG日志问题，提出了使用环形缓冲区和FIFO压缩模式的改进方案；针对快照修剪问题，提出了使用增量数据结构和优化算法的改进方案；针对代码重构，讨论了使用C++17 async库的可能性。会议决定后续将进行相关改进的实现和评估。</p>',19)])])}const u=t(i,[["render",r]]);export{d as __pageData,u as default};
